-- MTC billing migration source setup
-- Generated from TeamUp active/hold memberships + payment history export.
-- SAFE: this does not create Stripe subscriptions, collect money, or disable TeamUp billing.

create table if not exists public.mtc_billing_migration_source (
  id uuid primary key default gen_random_uuid(),
  customer_name text, customer_email text, membership_name text not null, membership_status text,
  teamup_processor text, teamup_start_date date, teamup_expiration_date date,
  last_payment_at timestamptz, last_payment_amount_pence integer, last_payment_membership text,
  match_quality text not null default 'none', imported_at timestamptz not null default now(),
  unique(customer_email, membership_name)
);

truncate table public.mtc_billing_migration_source;


-- Backfill payment dates/amounts onto matching TOTS records without changing collection state.
update public.store_subscriptions s set
  last_payment_at = coalesce(s.last_payment_at, src.last_payment_at),
  last_payment_amount_pence = coalesce(s.last_payment_amount_pence, src.last_payment_amount_pence),
  updated_at = now()
from public.mtc_billing_migration_source src
where s.organisation_id = '2c96d537-2be4-4917-8982-e7491300f15f'::uuid
  and lower(trim(coalesce(s.customer_email,''))) = lower(trim(coalesce(src.customer_email,'')))
  and (lower(trim(coalesce(s.legacy_membership_name,''))) = lower(trim(src.membership_name))
       or lower(trim(coalesce(s.metadata->>'teamup_membership',''))) = lower(trim(src.membership_name)));

-- Audit only
select match_quality, count(*) from public.mtc_billing_migration_source group by match_quality order by match_quality;
select count(*) as tots_collecting_now from public.store_subscriptions where organisation_id='2c96d537-2be4-4917-8982-e7491300f15f'::uuid and collection_enabled=true;
select count(*) as teamup_still_on from public.store_subscriptions where organisation_id='2c96d537-2be4-4917-8982-e7491300f15f'::uuid and teamup_billing_active=true;
